        assertEquals(1, listPopulation.getChromosomes().size());
    }

    @Test
    public void testConstructorWithTooLargeList() {
        List<Chromosome> chromosomes = new ArrayList<>();
        for (int i = 0; i < 11; i++) {
            chromosomes.add(new MockChromosome());
