        instance.setChromosomes(chromosomes);
        assertEquals(1, instance.getPopulationSize());
        assertEquals(1, instance.getChromosomes().size());
    }

    @Test
    public void testAddChromosomes() {
        instance.addChromosomes(Collections.singletonList(new MockChromosome()));
        assertEquals(1, instance.getPopulationSize());
        assertEquals(1, instance.getChromosomes().size());
    }

    @Test
    public void testGetChromosomesIterator() {
        List<Chromosome> chromosomes = new ArrayList<>();
        chromosomes.add(new MockChromosome());
        chromosomes.add(new MockChromosome());
        Iterator<Chromosome> iterator = instance.iterator();
        assertEquals(2, iterator.count());
        assertTrue(iterator.hasNext());
        Iterator<Chromosome> iterator2 = instance.iterator();
        assertTrue(iterator2.hasNext());
    }
}

